-- 521: Original BrillaPrep NSMQ subj_nsmq_physics round_one beta questions (batch 002).
-- Curriculum-aligned practice content; not official NSMQ (Primetime) material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_521_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_521_guard;
INSERT INTO _migration_521_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_phys_r1_b002_001' AND NOT (q.topic_id IS 'topic_nsmq_phys_kinematics' AND q.subject_id IS 'subj_nsmq_physics' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which physical quantity has the SI unit metres per second squared (m/s²)?' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. Acceleration","B. Velocity","C. Force","D. Momentum"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Acceleration is the change in velocity per unit time, so its unit is (m/s)/s = m/s². Velocity is m/s, force is the newton (kg·m/s²), and momentum is kg·m/s.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_phys_r1_b002_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_521_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_phys_r1_b002_002' AND NOT (q.topic_id IS 'topic_nsmq_phys_thermodynamics' AND q.subject_id IS 'subj_nsmq_physics' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which process transfers heat through a solid without any bulk movement of the material itself?' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. Convection","B. Conduction","C. Radiation","D. Evaporation"]' AND q.correct_answer IS 'B' AND q.explanation IS 'In conduction, vibrating particles pass kinetic energy to their neighbours while staying in fixed positions, which is how heat travels through solids. Convection requires bulk fluid movement, and radiation needs no medium at all.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_phys_r1_b002_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_521_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_phys_r1_b002_003' AND NOT (q.topic_id IS 'topic_nsmq_phys_modern_physics' AND q.subject_id IS 'subj_nsmq_physics' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The time taken for half of the unstable nuclei in a radioactive sample to decay is called the' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. Decay constant","B. Activity","C. Half-life","D. Binding energy"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The half-life t½ is the average time for half the nuclei to decay, and the activity falls by half in each half-life. The decay constant λ is related by t½ = ln 2/λ, but it is not itself a time.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_phys_r1_b002_003' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_521_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_phys_r1_b002_004' AND NOT (q.topic_id IS 'topic_nsmq_phys_mechanics' AND q.subject_id IS 'subj_nsmq_physics' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A resultant force of 20 N acts on a body of mass 4 kg. What acceleration is produced?' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. 80 m/s²","B. 0.2 m/s²","C. 24 m/s²","D. 5 m/s²"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Newton’s second law gives a = F/m = 20/4 = 5 m/s². Multiplying instead of dividing gives 80 m/s², inverting the ratio gives 0.2 m/s², and adding the numbers gives 24 m/s² — all common slips.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_phys_r1_b002_004' AND NOT (r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_phys_r1_b002_001', 'topic_nsmq_phys_kinematics', 'subj_nsmq_physics', 'exam_nsmq', NULL, NULL, 'Which physical quantity has the SI unit metres per second squared (m/s²)?', 'multiple_choice', 'round_one', '["A. Acceleration","B. Velocity","C. Force","D. Momentum"]', 'A', 'Acceleration is the change in velocity per unit time, so its unit is (m/s)/s = m/s². Velocity is m/s, force is the newton (kg·m/s²), and momentum is kg·m/s.', 'easy', '3', '1', '30', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, NULL);
