INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_phys_r1_b002_003', 'topic_nsmq_phys_modern_physics', 'subj_nsmq_physics', 'exam_nsmq', NULL, NULL, 'The time taken for half of the unstable nuclei in a radioactive sample to decay is called the', 'multiple_choice', 'round_one', '["A. Decay constant","B. Activity","C. Half-life","D. Binding energy"]', 'C', 'The half-life t½ is the average time for half the nuclei to decay, and the activity falls by half in each half-life. The decay constant λ is related by t½ = ln 2/λ, but it is not itself a time.', 'medium', '3', '1', '30', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_phys_r1_b002_004', 'topic_nsmq_phys_mechanics', 'subj_nsmq_physics', 'exam_nsmq', NULL, NULL, 'A resultant force of 20 N acts on a body of mass 4 kg. What acceleration is produced?', 'multiple_choice', 'round_one', '["A. 80 m/s²","B. 0.2 m/s²","C. 24 m/s²","D. 5 m/s²"]', 'D', 'Newton’s second law gives a = F/m = 20/4 = 5 m/s². Multiplying instead of dividing gives 80 m/s², inverting the ratio gives 0.2 m/s², and adding the numbers gives 24 m/s² — all common slips.', 'medium', '3', '1', '30', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'nsmq-expansion-beta-002', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM questions WHERE id IN ('q_nsmq_phys_r1_b002_001', 'q_nsmq_phys_r1_b002_002', 'q_nsmq_phys_r1_b002_003', 'q_nsmq_phys_r1_b002_004');
DELETE FROM _migration_521_guard;
INSERT INTO _migration_521_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions WHERE id IN ('q_nsmq_phys_r1_b002_001', 'q_nsmq_phys_r1_b002_002', 'q_nsmq_phys_r1_b002_003', 'q_nsmq_phys_r1_b002_004')) = 4 AND (SELECT COUNT(*) FROM question_content_releases r WHERE r.question_id IN ('q_nsmq_phys_r1_b002_001', 'q_nsmq_phys_r1_b002_002', 'q_nsmq_phys_r1_b002_003', 'q_nsmq_phys_r1_b002_004') AND r.batch_id IS 'nsmq-expansion-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 4 THEN 1 ELSE 0 END;
